import { registerWebComponents } from '@domg-wc/common';
import { VlHeader } from '@domg-wc/components/compliance';

registerWebComponents([VlHeader]);

// ready volgt op het element zelf zodra de widget de header in de pagina gezet heeft; het bubbelt niet.
document.querySelector('vl-header').addEventListener('ready', () => {
    console.log('ready');
});

