import { registerWebComponents } from '@domg-wc/common';
import { VlHeader } from '@domg-wc/components/compliance';

registerWebComponents([VlHeader]);

// vl-header leest applicationLinks één keer, nadat de widget geladen is: zet de property meteen, niet later.
document.querySelector('vl-header').applicationLinks = [
    { label: 'Link 1', href: 'https://example.com/link1' },
    { label: 'Link 2', href: 'https://example.com/link2' },
];
